def sum_digits(n):
    """
    Calculate the sum of all digits in a non-negative integer n.

    Args:
    n (int): A non-negative integer whose digits will be summed.

    Returns:
    int: The sum of all digits in n.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    def extract_digits(num):
        """Extract digits from a number."""
        while num > 0:
            yield num % 10
            num //= 10

    return sum(extract_digits(n))

