def reverse_words(s):
    """
    Reverse the order of words in the input string s.

    Args:
    s (str): The input string containing multiple words separated by spaces.

    Returns:
    str: A new string with the order of words reversed.
    """
    def helper(s, start=0, end=None):
        if end is None:
            end = len(s) - 1
        if start >= end:
            return ''
        word_start = start
        while word_start <= end and s[word_start] != ' ':
            word_start += 1

def reverse_string(s):
    """
    Reverses the order of characters in a string using recursion.
    """
    if len(s) == 0:
        return ""
    else:
        return s[-1] + reverse_string(s[:-1])

def reverse_words(s):
    """
    Reverses the order of words in a string s.
    """
    words = s.split()
    reversed_words = [reverse_string(word) for word in words]
    return ' '.join(reversed_words)

