def gcd(a, b):
    """Return the greatest common divisor of two positive integers a and b."""
    # Base case: if b is 0, then a is the GCD
    if b == 0:
        return a
    else:
        # Recursive case: call gcd with b and remainder of a divided by b
        return gcd(b, a % b)

