    return s == s[::-1]

def sum_digits(n: int) -> int:
    n_array = [i for I in range(10) if n // I == n % I == 0]
    sum_digits = 0
    for digit in n_array:
        sum_digits += digit
    return sum_digits

def sum_digits(n):
    """Function to calculate the sum of digits in a non-negative integer"""
    if n < 0:
        raise ValueError("Negative numbers are not allowed.")
    digits = []
    for I in range(10):
        digit = n // 10 ** I
        if digit >= 0:
            digits.append(digit)
        else:
            n -= digit ** I
    sum_ = 0
    for digit in digits:
        sum_ += digit
    return sum_

