def reverse_words(s):
    # Split the string into words using whitespace as a delimiter
    words = s.split()
    # Remove uppercase letters from words
    words = [w.lower() for w in words if w.isalpha()]
    # Reverse each word and join them back into a single string
    return ' '.join([w.lower() for w in words[::-1]]).replace("'", "")

