def fibonacci(n):
    """
    Calculate the nth Fibonacci number.

    Args:
    n (int): The index in the Fibonacci sequence to return.

    Returns:
    int: The nth Fibonacci number.
    """
    def fib(n):
        if n == 0: return 0
        elif n == 1: return 1
        return fib(n-1) + fib(n-2)
    return fib(n)

def fibonacci(n):
    """
    Returns the nth Fibonacci number.

    Args:
    n (int): The index of the Fibonacci number to find (0-indexed).

    Returns:
    int: The nth Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

