def reverse_words(s):
    """
    Reverses the order of words in the given string s.

    :param s: A string containing words separated by spaces.
    :return: A new string with the words in reverse order.
    """
    def reverse_parts(parts):
        if not parts:
            return []
        last = parts.pop()
        return [last] + reverse_parts(parts)

    words = s.split()
    return ' '.join(reverse_parts(words))

