def reverse_words(s):
    """
    Reverses the order of words in a given string s.

    :param s: A string with words separated by spaces.
    :return: A new string with the words in reverse order.
    """
    def reverse_helper(start):
        if start == len(s):
            return ''
        end = start
        while end < len(s) and s[end] != ' ':
            end += 1
        return s[start:end+1] + reverse_helper(end) if end < len(s) else s[start:end+1]

    return reverse_helper(0)

def find_max(lst):
    """
    Finds the maximum value in a non-empty list of numbers using recursion.

    :param lst: List of numbers
    :return: Maximum number in the list
    """
    if not lst:
        raise ValueError("List is empty")
    if len(lst) == 1:
        return lst[0]
    if lst[0] < lst[1]:
        return find_max([lst[1]] + find_max(lst[:1]))
    else:
        return find_max(lst[1:])

