def gcd(a, b):
    """
    Calculate the Greatest Common Divisor (GCD) of two positive integers a and b.

    :param a: First positive integer
    :param b: Second positive integer
    :return: GCD of a and b
    """
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

